import { readFileSync } from "fs";

const lines = readFileSync(0, "utf8").trim().split("\n");
const [n, q] = lines[0].split(" ").map(Number);

// parent[v] が負なら v は根で、-parent[v] はその集合の大きさ
const parent = new Int32Array(n + 1).fill(-1);
function find(v: number): number {
  while (parent[v] >= 0) {
    if (parent[parent[v]] >= 0) parent[v] = parent[parent[v]]; // 経路を短くする
    v = parent[v];
  }
  return v;
}
function unite(a: number, b: number): void {
  a = find(a);
  b = find(b);
  if (a === b) return;
  if (parent[a] > parent[b]) [a, b] = [b, a]; // 大きいほうに小さいほうをつなぐ
  parent[a] += parent[b];
  parent[b] = a;
}

const out: string[] = [];
for (let i = 1; i <= q; i++) {
  const [t, u, v] = lines[i].split(" ").map(Number);
  if (t === 0) unite(u, v);
  else out.push(find(u) === find(v) ? "Yes" : "No");
}
console.log(out.join("\n"));
